"""NodeCrypt: one-file FastAPI server and embedded E2EE web client.

The browser performs all message encryption. This server only authenticates
the relay connection, tracks live group members, and forwards ciphertext.
"""

from __future__ import annotations

import asyncio
import base64
import binascii
import json
import logging
import os
import secrets
import sqlite3
import tempfile
import threading
import time
from contextlib import asynccontextmanager
from pathlib import Path
from typing import Any

from cryptography.hazmat.primitives import hashes, serialization
from cryptography.hazmat.primitives.asymmetric import ec, padding, rsa
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
from fastapi import FastAPI, WebSocket, WebSocketDisconnect
from fastapi.middleware.cors import CORSMiddleware
from fastapi.responses import HTMLResponse, JSONResponse


LOGGER = logging.getLogger("nodecrypt")
logging.basicConfig(level=os.getenv("LOG_LEVEL", "INFO"))

HOST = os.getenv("HOST", "0.0.0.0")
PORT = int(os.getenv("PORT", "8000"))
SEEN_TIMEOUT = max(10, int(os.getenv("NODECRYPT_SEEN_TIMEOUT", "60")))
MAX_MESSAGE_SIZE = max(1024, int(os.getenv("NODECRYPT_MAX_MESSAGE_SIZE", str(8 * 1024 * 1024))))
MEMORY_ENABLED = os.getenv("NODECRYPT_MEMORY_ENABLED", "1").lower() not in {"0", "false", "no"}
MEMORY_RETENTION_DAYS = max(0, int(os.getenv("NODECRYPT_MEMORY_RETENTION_DAYS", "30")))
MEMORY_MAX_MESSAGES = max(1, int(os.getenv("NODECRYPT_MEMORY_MAX_MESSAGES", "1000")))
DATABASE_PATH = os.getenv(
    "NODECRYPT_DB_PATH",
    str(Path(tempfile.gettempdir()) / "nodecrypt" / "nodecrypt.sqlite3"),
)

# Live state is intentionally volatile. It contains keys only while a client
# is connected and never writes plaintext messages to disk.
clients: dict[str, dict[str, Any]] = {}
rooms: dict[str, set[str]] = {}
state_lock = asyncio.Lock()
cleanup_task: asyncio.Task[None] | None = None
server_private_key: Any = None
server_public_key = ""

database: sqlite3.Connection | None = None
database_lock = threading.RLock()

